#include "number-test-api.cpp"
#include <cstdio>
#include <vector>
#include <cstring>
#include <cstdlib>
static uint32_t read32(FILE*f,bool&ok){uint8_t b[4];if(std::fread(b,1,4,f)!=4){ok=false;return 0;}return uint32_t(b[0])|uint32_t(b[1])<<8|uint32_t(b[2])<<16|uint32_t(b[3])<<24;}
static void write32(FILE*f,uint32_t v){uint8_t b[4]={uint8_t(v),uint8_t(v>>8),uint8_t(v>>16),uint8_t(v>>24)};if(std::fwrite(b,1,4,f)!=4)std::abort();}
int main(int argc,char**argv){if(argc!=3)return 1;FILE*in=std::fopen(argv[1],"rb"),*out=std::fopen(argv[2],"wb");if(!in||!out)return 2;bool ok=true;uint32_t magic=read32(in,ok),count=read32(in,ok);if(!ok||magic!=0x53414231u||count>100000)return 3;write32(out,magic);write32(out,count);for(uint32_t i=0;i<count;i++){
 uint32_t op=read32(in,ok),ac=read32(in,ok),as=read32(in,ok),bc=read32(in,ok),bs=read32(in,ok),work=read32(in,ok),bytes=read32(in,ok);if(!ok||ac>512||bc>512||bytes<64||bytes>16*1024*1024)return 4;std::vector<uint32_t>a(ac?ac:1),b(bc?bc:1),values(4096,0x5a5a5a5a),result;std::vector<uint64_t>arena((bytes+7)/8);for(uint32_t j=0;j<ac;j++)a[j]=read32(in,ok);for(uint32_t j=0;j<bc;j++)b[j]=read32(in,ok);if(!ok)return 5;int32_t metadata[8];for(auto&v:metadata)v=0x5a5a5a5a;uint32_t status;
 if(op==11){if(ac%4||bc%4)return 6;std::vector<double>av(ac/2),bv(bc/2);for(uint32_t k=0;k<ac/2;k++){uint64_t bits=uint64_t(a[2*k])|uint64_t(a[2*k+1])<<32;std::memcpy(&av[k],&bits,8);}for(uint32_t k=0;k<bc/2;k++){uint64_t bits=uint64_t(b[2*k])|uint64_t(b[2*k+1])<<32;std::memcpy(&bv[k],&bits,8);}status=sabt_curve_pair(av.data(),ac/4,bv.data(),bc/4,arena.data(),bytes,work,values.data(),2048,metadata);if(!status)for(int32_t k=0;k<metadata[1];k++)result.push_back(values[(uint32_t)k]);}
 else if(op==10){if(ac%2)return 6;std::vector<double>coefficients(ac/2);for(uint32_t k=0;k<ac/2;k++){uint64_t bits=uint64_t(a[2*k])|uint64_t(a[2*k+1])<<32;std::memcpy(&coefficients[k],&bits,8);}status=sabt_polynomial_roots(coefficients.data(),ac/2,bc>1?b[1]:0,bc?b[0]:0,arena.data(),bytes,work,values.data(),2048,metadata);if(!status)for(int32_t k=0;k<metadata[1];k++)result.push_back(values[(uint32_t)k]);}
 else if(op==9){if(ac!=2)return 6;uint64_t bits=uint64_t(a[0])|uint64_t(a[1])<<32;double value,bounds[2];std::memcpy(&value,&bits,8);std::memset(bounds,0x5a,sizeof(bounds));uint32_t counts[3]={0x5a5a5a5a,0x5a5a5a5a,0x5a5a5a5a};status=sabt_rational_double(value,arena.data(),bytes,work,bounds,values.data(),4096,counts);if(!status){metadata[0]=(int32_t)counts[2];metadata[1]=(int32_t)counts[0];metadata[2]=(int32_t)counts[1];for(uint32_t k=3;k<8;k++)metadata[k]=0;for(uint32_t k=0;k<counts[0];k++)result.push_back(values[k]);for(uint32_t k=0;k<counts[1];k++)result.push_back(values[2048+k]);for(double v:bounds){std::memcpy(&bits,&v,8);result.push_back((uint32_t)bits);result.push_back((uint32_t)(bits>>32));}}else if(counts[0]!=0x5a5a5a5a||counts[1]!=0x5a5a5a5a||counts[2]!=0x5a5a5a5a)return 7;
 }else{status=sabt_number_operation(op,a.data(),ac,(int32_t)as,b.data(),bc,(int32_t)bs,arena.data(),bytes,work,values.data(),2048,metadata);if(!status)for(int32_t k=0;k<metadata[1];k++)result.push_back(values[(uint32_t)k]);}
 if(status){for(auto v:metadata)if(v!=0x5a5a5a5a)return 8;for(auto v:values)if(v!=0x5a5a5a5a)return 9;}write32(out,status);for(auto v:metadata)write32(out,(uint32_t)v);write32(out,(uint32_t)result.size());for(auto v:result)write32(out,v);
 }std::fclose(in);std::fclose(out);return 0;}
